arguments.content:
data {
  int<lower=1> N;
  array[N] int<lower=0> y;
  array[N] int<lower=0> n;
}

parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}

model {
  // The stated prior is an unnormalized density on alpha > 0, beta > 0.
  target += -2.5 * log(alpha + beta);

  for (i in 1:N) {
    theta[i] ~ beta(alpha, beta);
    y[i] ~ binomial(n[i], theta[i]);
  }
}

