     8	alpha_output <- "/app/posterior_alpha_mean.txt"
     9	beta_output <- "/app/posterior_beta_mean.txt"
    10	
    11	data <- read.csv(input_file, header = TRUE, stringsAsFactors = FALSE)
    12	if (!all(c("y", "n") %in% names(data))) {
    13	  stop("data.csv must contain columns named y and n")
    14	}
    15	if (anyNA(data$y) || anyNA(data$n) || any(data$y < 0) || any(data$n < data$y)) {
    16	  stop("The data must satisfy 0 <= y <= n with no missing values")
    17	}
    18	
    19	stan_data <- list(
    20	  N = nrow(data),
    21	  y = as.integer(data$y),
    22	  n = as.integer(data$n)
    23	)
    24	
    25	model <- rstan::stan_model(file = stan_file)
    26	fit <- rstan::sampling(
    27	  object = model,
    28	  data = stan_data,
    29	  chains = 4,
    30	  iter = 100000,
    31	  seed = 1,
    32	  cores = 4,
    33	  refresh = 1000,
    34	  control = list(adapt_delta = 0.99, max_treedepth = 15)
    35	)
    36	
    37	posterior <- rstan::extract(fit, pars = c("alpha", "beta"), permuted = TRUE)
    38	alpha_mean <- mean(posterior$alpha)
    39	beta_mean <- mean(posterior$beta)
    40	
    41	writeLines(sprintf("%.17g", alpha_mean), alpha_output)
    42	writeLines(sprintf("%.17g", beta_mean), beta_output)
